"@media(max-width:800px){.workspace{display:flex;flex-direction:column;gap:16px;padding:16px;margin:0}.mobile-meta{margin-left:auto;text-align:right;flex:none;font:14px/20px var(--sans)}.mobile-meta strong{color:var(--orange);display:block}.mobile-meta small{font:14px/20px var(--sans)}.topbar .header-title p{position:absolute;top:56px;left:138px;right:16px}.topbar{position:relative}.mobile-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);height:52px}.mobile-steps span{display:flex;align-items:center;justify-content:center;background:var(--surface);color:var(--muted);font:600 14px/20px var(--sans)}.mobile-steps .active{background:var(--orange);color:var(--black)}.mobile-steps .done{color:var(--green);background:var(--surface2)}.mobile-steps .fail{background:var(--red);color:var(--black)}.rail,.telemetry{display:none}.scan-panel{padding:8px 15px 16px;min-height:422px}.panel-heading{min-height:50px;gap:8px}.panel-heading h2{font-size:24px}.panel-actions{position:static;margin-left:auto;align-self:center}.filter{padding:5px 10px}.scan-count{font-size:14px;line-height:20px}.divider{margin:12px 0}.network-list{height:264px}.network-row{gap:16px;padding:10px 16px;grid-template-columns:4px minmax(0,1fr) 58px}.scan-bottom .divider,.scan-meta,.scan-selected{display:none}.scan-note{font:16px/24px var(--sans);margin-top:16px;min-height:48px}.right-column{gap:16px}.state-panel{padding:8px 15px 16px;min-height:0}.state-head .chip{min-width:112px}.state-title{font-size:24px;line-height:30px}.selected-meta{margin-top:8px}.credential-card{display:none}.field-label{margin-top:20px}.warning{margin-top:28px}.privacy{font-size:14px;line-height:20px;min-height:40px}.state-view>.primary{margin-top:20px}.progress-wrap{padding-top:12px}.ring{width:72px;height:72px}.ring:after{inset:5px}.ring span{font-size:24px}.joining-ssid{margin-top:16px}.joining-status{margin-top:16px}.progress-line{margin-top:20px;height:6px}.joining-log{margin-top:16px;font-size:16px;line-height:24px}.progress-wrap button{margin-top:24px}.ready-wrap{padding-top:8px}.check{font-size:64px;line-height:68px}.ready-title{font-size:28px}.ready-ssid{margin-top:8px}.lease{margin-top:16px;font-size:16px;line-height:24px}.ready-wrap button{margin-top:24px}.error-wrap{padding-top:16px}.error-status{font-size:16px;line-height:24px}.diagnostic{margin-top:16px;font-size:16px;line-height:24px;padding:8px 12px}.error-actions{margin-top:20px}.footer{margin:0 16px 16px;display:flex;justify-content:space-between;align-items:center;min-height:40px;gap:8px}.footer .desktop-only{display:none}.footer-local{color:var(--orange);font-size:14px;line-height:20px}.footer-state{font-size:14px;line-height:20px;color:var(--muted);text-align:right}.status-feedback{margin-top:8px}}\n"
".panel-heading{min-height:76px}@media(max-width:800px){.panel-heading{min-height:42px}}\n"
"@media(max-width:360px){.topbar{gap:8px}.brand{width:96px}.topbar .header-title p{left:120px;font-size:14px}.workspace{padding:12px}.network-row{grid-template-columns:4px minmax(0,1fr) 36px;gap:10px;padding:10px}.signal i{width:6px}.state-head .chip{min-width:88px}.panel-actions .filter{padding:5px}.footer{margin:0 12px 12px}}\n"
"</style></head>\n"
"<body><div class=\"app\">\n"
"<header class=\"topbar\"><div class=\"brand\">RYZOBEE</div><div class=\"header-title\"><h1><span class=\"desktop-only\">DEVICE </span>PROVISION</h1><p class=\"desktop-only\">LOCAL ACCESS POINT / SECURE SETUP</p><p class=\"mobile-only\">LOCAL AP \u00b7 <span id=\"ap-ip-mobile\">--</span></p></div><div class=\"header-detail desktop-only\"><small>DEVICE AP</small><strong id=\"ap-ip\">--</strong></div><span class=\"chip desktop-only\">2.4G ONLY</span><div class=\"header-detail header-session desktop-only\"><small>SESSION</small><strong id=\"session\">--</strong></div><div class=\"mobile-meta mobile-only\"><strong>2.4G</strong><small id=\"session-mobile\">--</small></div></header>\n"
"<main class=\"workspace\"><div class=\"mobile-steps\" id=\"mobile-steps\"><span data-step=\"scan\">SCAN</span><span data-step=\"key\">KEY</span><span data-step=\"link\">LINK</span><span data-step=\"ready\">READY</span></div>\n"
"<aside class=\"panel rail\"><div class=\"eyebrow\">FLOW 01 / 04</div><h2>PROVISION</h2><ol class=\"rail-steps\"><li data-step=\"scan\"><span class=\"num\">01</span>SCAN NETWORKS</li><li data-step=\"key\"><span class=\"num\">02</span>ACCESS KEY</li><li data-step=\"link\"><span class=\"num\">03</span>LINK DEVICE</li><li data-step=\"ready\"><span class=\"num\">04</span>READY</li></ol><section class=\"device-card\"><div class=\"eyebrow\">TARGET DEVICE</div><h3>RYZOBEE S3</h3><div id=\"device-online\" class=\"device-online\">AP STATUS --</div><div class=\"device-row\"><span>MCU</span><span>ESP32-S3</span></div><div class=\"device-row\"><span>RADIO</span><span>2.4 GHZ</span></div><div class=\"device-row\"><span>SECURITY</span><span>LOCAL AP</span></div><div class=\"device-row\"><span>SESSION</span><span id=\"session-age\">--</span></div></section></aside>\n"
"<section class=\"panel scan-panel\"><div class=\"panel-heading\"><div><div class=\"eyebrow desktop-only\">NETWORK SCAN / LIVE</div><h2><span class=\"desktop-only\">AVAILABLE </span>2.4G NETWORKS</h2><div id=\"scan-count\" class=\"scan-count\">WAITING FOR DEVICE</div></div><div class=\"panel-actions\"><span id=\"filter\" class=\"filter\" role=\"status\"><span class=\"desktop-only\">2.4G FILTER</span><span class=\"mobile-only\">2.4G ONLY</span></span><button id=\"rescan\" class=\"secondary desktop-only\" type=\"button\">RESCAN</button></div></div><div class=\"divider\"></div><div id=\"network-list\" class=\"network-list scroll\" tabindex=\"0\" aria-label=\"Available networks\"><div class=\"empty-row\">WAITING FOR DEVICE</div></div><div class=\"scan-bottom\"><div class=\"divider\"></div><div class=\"scan-meta\"><span id=\"channels\">CHANNELS --</span><span id=\"rssi-range\">RSSI RANGE --</span></div><p id=\"scan-note\" class=\"scan-note\">2.4 GHz only \u00b7 scroll networks</p><div id=\"scan-selected\" class=\"scan-selected\">SELECT A NETWORK</div></div></section>\n"
"<div class=\"right-column\"><section class=\"panel state-panel\" aria-label=\"Connection status\"><div id=\"view-select\" class=\"state-view active\"><div class=\"state-head\"><div><div class=\"eyebrow desktop-only\">ACCESS CREDENTIALS</div><h2 class=\"state-title\">AUTHORIZE LINK</h2></div><span class=\"chip\" id=\"selection-chip\">SELECT</span></div><div id=\"selected-meta\" class=\"selected-meta mobile-only\">SELECT A NETWORK</div><div class=\"credential-card\"><strong id=\"selected-ssid\">--</strong><small id=\"selected-network-meta\">CH -- \u00b7 2.4 GHz</small></div><div id=\"manual-wrap\" hidden><label class=\"field-label\" for=\"manual-ssid\">NETWORK SSID</label><input id=\"manual-ssid\" class=\"manual-input\" maxlength=\"32\" autocomplete=\"off\" placeholder=\"Type SSID manually\"><button id=\"rescan-mobile\" type=\"button\" class=\"secondary\">RESCAN NETWORKS</button></div><label class=\"field-label\" for=\"password\">ACCESS PASSWORD</label><div class=\"password-wrap\"><input id=\"password\" type=\"password\" maxlength=\"63\" autocomplete=\"current-password\" placeholder=\"Enter network password\"><button id=\"show-password\" type=\"button\" aria-label=\"Show password\">SHOW</button></div><div class=\"field-hint\">LOCAL AP SESSION \u00b7 <span id=\"password-state\">MASKED</span></div><div class=\"warning\">2.4 GHz only \u00b7 verify password before continuing.</div><button id=\"connect\" class=\"primary\" type=\"button\" disabled>CONNECT DEVICE</button><div class=\"privacy\">Credentials are stored on this device for automatic reconnection.</div></div>\n"
"<div id=\"view-joining\" class=\"state-view\"><div class=\"state-head\"><div><div class=\"eyebrow desktop-only\">CONNECTION SEQUENCE</div><h2 class=\"state-title\">CONNECTING</h2></div><span class=\"chip\">JOINING</span></div><div class=\"progress-wrap\"><div id=\"ring\" class=\"ring\"><span id=\"progress\">--</span></div><div id=\"joining-ssid\" class=\"joining-ssid\">--</div><div class=\"joining-status\">CONNECTING TO NETWORK</div><div class=\"progress-line\"><span id=\"progress-line\"></span></div><div id=\"joining-log\" class=\"joining-log\">Waiting for the device connection result.</div><button id=\"cancel\" class=\"secondary\" type=\"button\">CANCEL</button></div></div>\n"
"<div id=\"view-ready\" class=\"state-view\"><div class=\"state-head\"><div><div class=\"eyebrow desktop-only\">LINK COMPLETE</div><h2 class=\"state-title\">DEVICE ONLINE</h2></div><span class=\"chip green\">CONNECTED</span></div><div class=\"ready-wrap\"><div class=\"check\" aria-hidden=\"true\">\u2713</div><div class=\"ready-title\">WI-FI READY</div><div id=\"ready-ssid\" class=\"ready-ssid\">--</div><div class=\"lease\"><span id=\"ready-ip\">IPv4 --</span><span>DHCP \u00b7 2.4 GHz</span></div><button id=\"dashboard\" class=\"primary\" type=\"button\">OPEN DEVICE DASHBOARD</button><p class=\"caption muted\" id=\"dashboard-note\">No dashboard service is advertised by this firmware.</p></div></div>\n"
"<div id=\"view-failed\" class=\"state-view\"><div class=\"state-head\"><div><div class=\"eyebrow desktop-only\" style=\"color:var(--red)\">LINK FAILED</div><h2 class=\"state-title\">CHECK NETWORK</h2></div><span class=\"chip red\">FAILED</span></div><div class=\"error-wrap\"><div id=\"error-code\" class=\"error-code\">E_WIFI_CONNECT</div><div id=\"error-status\" class=\"error-status\">CONNECTION FAILED</div><div class=\"diagnostic\"><div class=\"bad\"><span>01</span><span id=\"diagnostic-cause\">Check the connection settings.</span></div><div class=\"warn\"><span>02</span><span>Confirm the router uses 2.4 GHz.</span></div><div class=\"muted\"><span>03</span><span id=\"credential-policy\">Credential status unknown.</span></div></div><div class=\"actions error-actions\"><button id=\"change\" class=\"secondary\" type=\"button\"><span class=\"desktop-only\">CHANGE NETWORK</span><span class=\"mobile-only\">CHANGE</span></button><button id=\"retry\" class=\"primary\" type=\"button\">RETRY</button></div><div class=\"error-privacy\">Verify the password before retrying. 5 GHz cannot be used.</div></div></div><div class=\"status-feedback\" id=\"feedback\" role=\"status\" aria-live=\"polite\"></div></section>\n"
"<section class=\"panel telemetry\"><div class=\"telemetry-head\"><div><div class=\"eyebrow\">LIVE LINK TELEMETRY</div><h3 id=\"telemetry-title\">STANDBY</h3></div><span id=\"telemetry-chip\" class=\"chip\">IDLE</span></div><div class=\"telemetry-segments\" id=\"telemetry-segments\"><i></i><i></i><i></i><i></i></div><div class=\"metrics\"><div class=\"metric\"><label>AP RSSI</label><strong id=\"metric-rssi\">--</strong></div><div class=\"metric\"><label>SCAN</label><strong id=\"metric-scan\">--</strong></div><div class=\"metric\"><label>DHCP WAIT</label><strong id=\"metric-dhcp\">--</strong></div><div class=\"metric\"><label>TIMEOUT</label><strong id=\"metric-timeout\">--</strong></div></div><div id=\"telemetry-log\" class=\"telemetry-log\">Waiting for device status.</div></section></div></main>\n"
"<footer class=\"footer\"><div class=\"footer-session desktop-only\">LOCAL SESSION \u00b7 <span id=\"footer-session\">--</span></div><div id=\"footer-log\" class=\"footer-log desktop-only\">Waiting for network scan.</div><div class=\"footer-cancel desktop-only\">ESC CANCEL LINK</div><div class=\"footer-version desktop-only\">WEB PROVISIONER V0.5 \u00b7 LOCAL ONLY</div><div id=\"footer-local\" class=\"footer-local mobile-only\">-- / LOCAL</div><div id=\"footer-state\" class=\"footer-state mobile-only\">CONNECTING</div></footer></div><script>/* Only the C provisioning service owns radio configuration and saved keys. */\n"
"'use strict';\n"
"const $ = id => document.getElementById(id);\n"
"const model = {status:null,networks:[],selected:null,visible:'select',busy:false,online:false,scanRequested:false,scanKey:'',editFailure:false,requesting:false,drag:null};\n"
"const kindOf = state => state === 'ONLINE' \? 'ready' : ['CONNECTING','CREDENTIALS_RECEIVED'].includes(state) \? 'joining' : state === 'FAILED' \? 'failed' : 'select';\n"
"const networkKey = n => JSON.stringify([n.ssid,n.auth,n.channel]);\n"
"const age = seconds => {const n=Math.max(0,Number(seconds)||0);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};\n"
"const keyBytes = value => new TextEncoder().encode(value).length;\n"
"const secured = () => model.selected && model.selected.auth !== 'OPEN';\n"
"const locked = () => model.busy || model.visible === 'joining' || model.visible === 'ready' || !model.online;\n"
"function syncControls(){\n"
"  const key=$('password').value,n=model.selected,valid=n&&keyBytes(n.ssid)<=32&&(!secured()||(keyBytes(key)>=8&&keyBytes(key)<=63));\n"
"  $('connect').disabled=locked()||!valid;$('retry').disabled=locked()||!valid;\n"
"  $('rescan').disabled=locked();$('rescan-mobile').disabled=locked();$('change').disabled=model.busy||!model.online;\n"
"  $('cancel').disabled=model.busy||!model.online;\n"
"  document.querySelectorAll('.network-row').forEach(row=>row.disabled=locked());\n"
"}\n"
"function selectNetwork(n){if(locked())return;model.selected=n;model.editFailure=true;$('password').value='';$('manual-ssid').value='';maskPassword();showSelection();renderRows();setView('select');syncControls();}\n"
"function showSelection(){const n=model.selected;const title=n\?n.ssid:'SELECT A NETWORK',meta=n\?(n.auth||'OPEN')+' \u00b7 CH '+(n.channel||'--')+' \u00b7 2.4 GHz':'CH -- \u00b7 2.4 GHz';$('selected-ssid').textContent=title;$('selected-network-meta').textContent=meta;$('selected-meta').textContent=n\?title+' / '+(n.auth||'OPEN')+' / CH '+(n.channel||'--'):title;$('scan-selected').textContent=n\?'SELECTED '+title:title;$('selection-chip').textContent=n\?'SELECTED':'SELECT';$('password').disabled=n&&n.auth==='OPEN';}\n"
"function renderRows(){\n"
"  const list=$('network-list'),top=list.scrollTop;list.replaceChildren();\n"
"  if(!model.networks.length){const empty=document.createElement('div');empty.className='empty-row';empty.textContent=['running','queued'].includes(model.status\?.scan_state)\?'SCANNING 2.4G CHANNELS...':'NO NETWORKS \u00b7 ENTER SSID BELOW';list.append(empty);}\n"
"  for(const n of model.networks){const row=document.createElement('button');row.type='button';row.className='network-row'+(model.selected&&networkKey(model.selected)===networkKey(n)\?' selected':'');row.setAttribute('aria-pressed',String(row.classList.contains('selected')));row.setAttribute('aria-label',n.ssid+' '+n.auth+' channel '+n.channel);row.disabled=locked();const bar=document.createElement('span');bar.className='bar';const info=document.createElement('span'),name=document.createElement('span'),meta=document.createElement('span');name.className='ssid';name.textContent=n.ssid;meta.className='meta';meta.textContent=(n.auth||'OPEN')+' \u00b7 CH '+n.channel+' \u00b7 2.4 GHz';info.append(name,meta);const signal=document.createElement('span');signal.className='signal';signal.setAttribute('aria-label',Number.isFinite(n.rssi)\?n.rssi+' dBm':'Signal unavailable');const count=!Number.isFinite(n.rssi)\?0:n.rssi>=-50\?4:n.rssi>=-65\?3:n.rssi>=-75\?2:1;for(let i=0;i<4;i++){const b=document.createElement('i');b.className=i<count\?'on':'';signal.append(b);}row.append(bar,info,signal);row.addEventListener('click',e=>{if(model.drag\?.moved){e.preventDefault();return;}selectNetwork(n);});list.append(row);}\n"
"  list.scrollTop=top;\n"
"}\n"
"function setView(kind){if(model.visible!==kind)maskPassword();model.visible=kind;document.querySelectorAll('.state-view').forEach(v=>v.classList.toggle('active',v.id==='view-'+kind));const active=kind==='select'\?'scan':kind==='ready'\?'ready':'link';document.querySelectorAll('[data-step]').forEach(el=>{const step=el.dataset.step;el.className=kind==='failed'&&step==='link'\?'fail':step===active\?'active':kind!=='select'&&['scan','key'].includes(step)||kind==='ready'\?'done':'';});}\n"
"function render(s){\n"
"  const prior=model.status;model.status=s;model.online=true;\n"
"  if(s.state!=='FAILED')model.editFailure=false;\n"
"  const state=kindOf(s.state),kind=state==='failed'&&model.editFailure\?'select':state;setView(kind);\n"
"  const incoming=(Array.isArray(s.networks)\?s.networks:[]).filter(n=>n&&typeof n.ssid==='string'&&n.ssid&&Number(n.channel)>=1&&Number(n.channel)<=14);\n"
"  const signature=JSON.stringify(incoming),changed=signature!==model.scanKey;\n"
"  if(changed){model.scanKey=signature;model.networks=incoming;if(model.selected&&!model.selected.manual&&!incoming.some(n=>networkKey(n)===networkKey(model.selected))&&kind==='select'){model.selected=null;$('password').value='';$('feedback').textContent='The selected network changed. Select it again.';}renderRows();}\n"
"  if(!prior||prior.scan_state!==s.scan_state)renderRows();\n"
"  const session=s.session||'--',ip=s.portal_ip||'--',busyScan=['running','queued'].includes(s.scan_state);$('session').textContent=session;$('session-mobile').textContent=session.replace(/^RZB-/,'');$('footer-session').textContent=session;$('ap-ip').textContent=ip;$('ap-ip-mobile').textContent=ip;$('footer-local').textContent=ip+' / LOCAL';$('session-age').textContent=age(s.portal_session_elapsed_s);$('device-online').textContent=s.portal_active\?'\u25cf AP ONLINE':'AP INACTIVE';\n"
"  const retained=model.networks.length,total=Math.max(retained,Number(s.scan_total)||0);$('scan-count').textContent=busyScan\?'SCANNING...':String(retained).padStart(2,'0')+' FOUND'+(total>retained\?' / '+total+' DETECTED':'');$('scan-note').textContent=s.scan_state==='failed'\?'Scan unavailable \u00b7 enter the SSID manually.':total>retained\?'Showing '+retained+' of '+total+' detected networks. Rescan to refresh.':'2.4 GHz only \u00b7 scroll networks';$('channels').textContent='CHANNELS '+((s.scan_channels||[]).join(' / ')||'--');$('rssi-range').textContent=Number.isFinite(s.scan_rssi_min)\?'RSSI RANGE '+s.scan_rssi_min+' \u2192 '+s.scan_rssi_max+' dBm':'RSSI RANGE --';$('manual-wrap').hidden=!!retained||busyScan;\n"
"  showSelection();\n"
"  const progress=Number.isFinite(s.connect_progress)\?Math.min(100,Math.max(0,s.connect_progress)):null;$('progress').textContent=progress===null\?'--':progress+'%';$('ring').style.setProperty('--progress',(progress||0)+'%');$('progress-line').style.width=(progress||0)+'%';$('joining-ssid').textContent=s.sta_ssid||model.selected\?.ssid||'--';$('joining-log').textContent='Waiting for network confirmation \u00b7 '+(s.connect_timeout_remaining_s\?\?'--')+' s remaining.';$('ready-ssid').textContent=s.sta_ssid||'--';$('ready-ip').textContent='IPv4 '+(s.ipv4||'--');\n"
"  /* ONLINE proves STA + IP, not a dashboard/HTTP service at that address. */\n"
"  $('dashboard').disabled=true;\n"
"  const error=s.error_code||'E_WIFI_CONNECT',timeout=error==='E_WIFI_TIMEOUT',missing=error==='E_WIFI_NOT_FOUND',auth=error==='E_WIFI_AUTH';$('error-code').textContent=error;$('error-status').textContent=timeout\?'CONNECTION TIMEOUT':missing\?'NETWORK NOT FOUND':auth\?'AUTHENTICATION REJECTED':'CONNECTION FAILED';$('diagnostic-cause').textContent=timeout\?'Router did not answer before the deadline.':missing\?'Selected network was not found on 2.4 GHz.':auth\?'Password may be incorrect.':'Check router availability and connection settings.';$('credential-policy').textContent=s.credentials_stored\?'Credentials are retained on this device.':'No credential was stored.';\n"
"  const title=kind==='ready'\?'READY':kind==='joining'\?'CONNECTING':kind==='failed'\?'FAILED':'STANDBY';$('telemetry-title').textContent=title;$('telemetry-chip').textContent=kind==='ready'\?'ONLINE':kind==='joining'\?'LINKING':kind==='failed'\?'FAILED':'IDLE';$('telemetry-chip').className='chip '+(kind==='ready'\?'green':kind==='failed'\?'red':'');$('metric-rssi').textContent=Number.isFinite(s.ap_rssi_dbm)\?s.ap_rssi_dbm+' dBm':'--';$('metric-scan').textContent=Number(s.scan_elapsed_ms)>0\?(s.scan_elapsed_ms/1000).toFixed(1)+' s':'--';$('metric-dhcp').textContent=kind==='ready'\?'DONE':'--';$('metric-timeout').textContent=kind==='joining'\?(s.connect_timeout_remaining_s\?\?'--')+' s':'--';const message=kind==='ready'\?'DHCP lease acquired \u00b7 device online':kind==='failed'\?error:busyScan\?'Scanning supported networks.':'Waiting for credentials.';$('telemetry-log').textContent=message;$('telemetry-log').classList.toggle('error',kind==='failed');$('footer-log').textContent=message;$('footer-state').textContent=kind==='joining'\?'TIMEOUT '+(s.connect_timeout_remaining_s\?\?'--')+'s':kind==='ready'\?'ONLINE':kind==='failed'\?error:'SESSION '+age(s.portal_session_elapsed_s);\n"
"  const segments={select:['orange','','',''],joining:['','orange','orange',''],ready:['on','on','on','on'],failed:['on','on','red','']};document.querySelectorAll('#telemetry-segments i').forEach((e,i)=>e.className=segments[kind][i]);syncControls();\n"
"}\n"
"async function request(url,body){const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),8000);try{const r=await fetch(url,{method:body===undefined\?'GET':'POST',cache:'no-store',headers:body===undefined\?{}:{'Content-Type':'application/json'},body:body===undefined\?undefined:JSON.stringify(body),signal:abort.signal});if(!r.ok)throw Error('Device request rejected ('+r.status+').');return r;}finally{clearTimeout(timeout);}}\n"
"async function poll(){if(model.requesting)return;model.requesting=true;try{const r=await request('/api/status');render(await r.json());if(!model.scanRequested&&model.status.scan_state==='idle'){model.scanRequested=true;await request('/api/scan',{});}}catch(e){model.online=false;$('feedback').textContent='LOCAL LINK OFFLINE \u00b7 reconnect to the device network.';$('telemetry-log').textContent='Portal link unavailable.';syncControls();}finally{model.requesting=false;}}\n"
"async function scan(){if(locked())return;model.busy=true;model.scanRequested=true;syncControls();try{await request('/api/scan',{});$('feedback').textContent='';}catch(e){$('feedback').textContent=e.message;}finally{model.busy=false;await poll();syncControls();}}\n"
"async function submit(){syncControls();if($('connect').disabled)return;model.busy=true;syncControls();try{await request('/api/provision',{ssid:model.selected.ssid,password:secured()\?$('password').value:''});model.editFailure=false;setView('joining');maskPassword();$('feedback').textContent='';}catch(e){$('feedback').textContent=e.message;}finally{model.busy=false;await poll();syncControls();}}\n"
"async function cancel(){if(model.busy||!model.online)return;model.busy=true;syncControls();try{await request('/api/cancel',{});model.selected=null;model.editFailure=false;$('password').value='';$('manual-ssid').value='';setView('select');$('feedback').textContent='';}catch(e){$('feedback').textContent=e.message;}finally{model.busy=false;await poll();syncControls();}}\n"
"function maskPassword(){$('password').type='password';$('show-password').textContent='SHOW';$('show-password').setAttribute('aria-label','Show password');$('password-state').textContent='MASKED';}\n"
"$('password').addEventListener('input',syncControls);$('manual-ssid').addEventListener('input',()=>{const ssid=$('manual-ssid').value;model.selected=ssid\?{ssid,auth:'WPA2',channel:'--',manual:true}:null;showSelection();syncControls();});$('show-password').onclick=()=>{const show=$('password').type==='password';$('password').type=show\?'text':'password';$('show-password').textContent=show\?'HIDE':'SHOW';$('show-password').setAttribute('aria-label',show\?'Hide password':'Show password');$('password-state').textContent=show\?'VISIBLE':'MASKED';};document.addEventListener('visibilitychange',()=>{if(document.hidden)maskPassword();});window.addEventListener('blur',maskPassword);\n"
"$('connect').onclick=submit;$('retry').onclick=submit;$('cancel').onclick=cancel;$('rescan').onclick=scan;$('rescan-mobile').onclick=scan;$('change').onclick=()=>{if(locked())return;model.editFailure=true;model.selected=null;$('password').value='';showSelection();renderRows();setView('select');syncControls();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&model.visible==='joining')cancel();});\n"
"/* Keep each pointer gesture in its original scroll owner. A drag never selects. */\n"
"const list=$('network-list');list.addEventListener('pointerdown',e=>{model.drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};});list.addEventListener('pointermove',e=>{const d=model.drag;if(d&&d.id===e.pointerId&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>8)d.moved=true;});list.addEventListener('pointercancel',()=>{if(model.drag)model.drag.moved=true;});list.addEventListener('scroll',()=>{if(model.drag)model.drag.moved=true;},{passive:true});\n"
"setInterval(poll,1000);poll();\n"
"</script></body></html>\n";
