"<body><header class=\"topbar\"><div class=\"brand\">RYZOBEE</div><div class=\"header-title\"><h1><span class=\"desktop-only\">LOCAL DIAGNOSTICS</span><span class=\"mobile-only\">FAULT REPORT</span></h1><p class=\"desktop-only\">SCRIPT FAULT / CAPTURED REPORT</p><p class=\"mobile-only\"><span data-field=\"id\">--</span> \u00b7 READ ONLY</p></div><div class=\"header-context desktop-only\"><div>REPORT <span data-field=\"id\">--</span></div><p>LOCAL NETWORK / READ ONLY</p></div></header>\n"
"<main id=\"status-view\" class=\"status-page\"><section class=\"panel status-panel\"><div class=\"status-stripe\"></div><h2 id=\"status-title\">LOADING CAPTURE</h2><h2 id=\"expired-title\" hidden>THIS CAPTURE IS GONE</h2><p id=\"status-description\">Waiting for the device to return this report. Content appears only after the snapshot is received.</p><div id=\"status-footer\" class=\"caption muted\">REQUEST IN PROGRESS</div><button id=\"retry-load\" class=\"primary\" type=\"button\" hidden>RETRY CONNECTION</button></section><section id=\"recover\" class=\"panel\" hidden><h3>RECOVER THE LINK</h3><p>1 Reconnect to the device network.<br>2 Scan the latest QR on the device.<br>3 Save the new capture before reboot.</p></section><p id=\"retry-hint\" class=\"muted\" hidden>An old link never silently opens a different script\u2019s report. Retry checks this report only. It does not run or restart a script.</p></main>\n"
"<main id=\"report-view\" class=\"report-page\" hidden>\n"
"<section class=\"panel fault-summary\"><div class=\"status-stripe\"></div><div class=\"fault-code\"><h2 data-field=\"code\">--</h2><p>SCRIPT HALTED</p></div><div class=\"fault-cause\"><h2 data-field=\"summary\">--</h2><div class=\"fault-file\"><span data-field=\"source_file\">--</span> : <span data-field=\"line\">--</span></div><p class=\"desktop-only\">Inspect the captured error below. Unavailable fields are marked --.</p></div><div class=\"fault-phase desktop-only\"><h3 data-field=\"phase\">--</h3><p class=\"caption muted\">CAPTURED PHASE</p></div></section>\n"
"<div class=\"actions report-actions mobile-only\"><button class=\"secondary\" data-action=\"copy-report\" type=\"button\">COPY REPORT</button><button class=\"primary\" data-action=\"download\" type=\"button\">DOWNLOAD .TXT</button></div>\n"
"<section class=\"panel context\"><h3>REPORT CONTEXT</h3><dl id=\"context-fields\" class=\"context-fields scroll\" tabindex=\"0\" aria-label=\"Report context\"><div><dt>DEVICE</dt><dd>RYZOBEE S3</dd></div><div><dt>FIRMWARE</dt><dd data-field=\"firmware_version\">--</dd></div><div class=\"source-context\"><dt>SOURCE FILE</dt><dd data-field=\"source_file\">--</dd></div><div><dt>PHASE</dt><dd data-field=\"phase\">--</dd></div><div><dt>JOB ID</dt><dd data-field=\"job_id\">--</dd></div><div><dt>ELAPSED</dt><dd data-field=\"duration_ms\">--</dd></div><div><dt>PEAK MEMORY</dt><dd data-field=\"peak_bytes\">--</dd></div><div><dt>CLEANUP</dt><dd data-field=\"cleanup_ok\">--</dd></div><div><dt>LUA RESULT</dt><dd data-field=\"lua_ok\">--</dd></div><div><dt>OVERALL RESULT</dt><dd data-field=\"ok\">--</dd></div></dl><div class=\"context-retention\"><div class=\"caption muted\">TEMPORARY SNAPSHOT</div><p>Save this capture now. Reboot, replacement or expiry makes this report unavailable.</p></div></section>\n"
"<section class=\"panel captured-error\"><div class=\"section-head\"><h3>CAPTURED ERROR</h3><button class=\"secondary desktop-only\" data-action=\"copy-error\" type=\"button\">COPY ERROR</button></div><div class=\"error-content scroll\" tabindex=\"0\" aria-label=\"Captured error and trace\"><pre id=\"raw-error\"></pre><pre id=\"trace\"></pre></div><p id=\"error-limit\" class=\"caption muted\" hidden>CAPTURE LIMITED / The stored error reached its capture limit.</p></section>\n"
"<section class=\"panel captured-output\"><div class=\"section-head\"><h3>CAPTURED OUTPUT</h3><div class=\"actions desktop-only\"><button class=\"secondary\" data-action=\"copy-report\" type=\"button\">COPY REPORT</button><button class=\"primary\" data-action=\"download\" type=\"button\">DOWNLOAD .TXT</button></div></div><div class=\"notice\" id=\"output-limit\" hidden>CAPTURE LIMITED / Earlier output was omitted. This is not a complete execution history.</div><div id=\"output-content\" class=\"output-content scroll\" tabindex=\"0\" aria-label=\"Captured output\"><pre id=\"output\"></pre></div><div id=\"empty-output\" class=\"empty-output\" hidden><h3>NO CAPTURED OUTPUT</h3><p>No output was captured for this run. The error message and available metadata are still shown above.</p><div class=\"caption muted\">NO OUTPUT \u2260 NO ERROR</div></div><p class=\"snapshot-status\">STATIC SNAPSHOT / NOT LIVE</p><p class=\"output-safety desktop-only\">Read-only diagnostics. No device commands, file upload, or automatic script restart.</p></section>\n"
"<p class=\"mobile-retention mobile-only\">Temporary capture. Save before reboot, expiry or replacement. Scrub secrets before sharing.</p><p id=\"encoding-note\" class=\"status-feedback\" hidden>TEXT ENCODING NOTICE / Invalid UTF-8 bytes were replaced with \? for display.</p><div id=\"action-status\" class=\"status-feedback\" role=\"status\" aria-live=\"polite\"></div>\n"
"</main><footer class=\"footer\"><span id=\"local-address\">LOCAL LINK / NO CLOUD UPLOAD</span><span class=\"desktop-only\">SCRUB SECRETS BEFORE SHARING</span></footer><script>'use strict';\n"
"const $=id=>document.getElementById(id);\n"
"const match=location.pathname.match(/^\\/f\\/([0-9a-f]{8})$/);\n"
"const id=match\?match[1]:'';\n"
"const cap=new URLSearchParams(location.search).get('cap')||'';\n"
"const endpoint=id&&/^[0-9a-f]{32}$/.test(cap)\?'/api/diagnostics/'+id+'\?cap='+encodeURIComponent(cap):null;\n"
"let report=null,loading=false;\n"
"function field(name,value){document.querySelectorAll('[data-field=\"'+name+'\"]').forEach(e=>e.textContent=value===null||value===undefined||value===''\?'--':String(value));}\n"
"field('id',id||'--');\n"
"function state(kind){\n"
"  $('report-view').hidden=true;$('status-view').hidden=false;$('status-view').dataset.state=kind;\n"
"  $('recover').hidden=kind!=='expired';$('retry-hint').hidden=kind!=='expired';$('expired-title').hidden=kind!=='expired';\n"
"  $('retry-load').hidden=kind==='loading';$('status-footer').hidden=kind!=='loading';\n"
"  const copy={loading:['LOADING CAPTURE','Waiting for the device to return this report. Content appears only after the snapshot is received.'],offline:['LOCAL LINK OFFLINE','The page cannot reach the device. Check Wi-Fi or the protected device AP, then retry this report link.'],expired:['REPORT UNAVAILABLE','The device no longer has this report. It may have restarted, replaced the capture, or closed the local session.']};\n"
"  $('status-title').textContent=copy[kind][0];$('status-description').textContent=copy[kind][1];\n"
"  $('retry-load').textContent=kind==='expired'\?'CHECK THIS LINK AGAIN':'RETRY CONNECTION';\n"
"}\n"
"function render(value){report=value;for(const name of ['id','phase','code','summary','source_file','job_id','firmware_version','line'])field(name,value[name]);field('duration_ms',Number.isFinite(value.duration_ms)\?value.duration_ms.toLocaleString()+' ms':null);field('peak_bytes',Number.isFinite(value.peak_bytes)\?(value.peak_bytes/1024).toFixed(1)+' KiB':null);field('cleanup_ok',value.cleanup_ok===true\?'No cleanup error':value.cleanup_ok===false\?'Cleanup failed':null);field('lua_ok',value.lua_ok===true\?'Passed':value.lua_ok===false\?'Failed':null);field('ok',value.ok===true\?'Passed':value.ok===false\?'Failed':null);$('raw-error').textContent=value.error||'--';$('trace').textContent=value.trace||'TRACE NOT CAPTURED';$('output').textContent=value.output||'';$('output-content').hidden=!value.output;$('empty-output').hidden=!!value.output;$('output-limit').hidden=!value.output_truncated;$('error-limit').hidden=!value.error_truncated;$('encoding-note').hidden=!value.text_sanitized;$('status-view').hidden=true;$('report-view').hidden=false;$('local-address').textContent='LOCAL LINK \u00b7 '+location.hostname+' / NO CLOUD UPLOAD';}\n"
"async function load(){if(loading)return;if(!endpoint){state('expired');return;}loading=true;state('loading');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(endpoint,{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});if([400,403,404,410].includes(response.status)){report=null;state('expired');return;}if(!response.ok)throw Error('unavailable');const value=await response.json();if(value.id!==id)throw Error('report identity changed');render(value);}catch{state('offline');}finally{clearTimeout(timer);loading=false;}}\n"
"function textReport(){if(!report)return'';const r=report,unknown=v=>v===null||v===undefined\?'--':String(v);return['RYZOBEE / CAPTURED REPORT '+r.id,'STATIC SNAPSHOT / NOT LIVE','SOURCE FILE: '+unknown(r.source_file),'JOB ID: '+unknown(r.job_id),'FIRMWARE: '+unknown(r.firmware_version),'PHASE: '+unknown(r.phase),'CODE: '+unknown(r.code),'LINE: '+unknown(r.line),'ELAPSED MS: '+unknown(r.duration_ms),'PEAK BYTES: '+unknown(r.peak_bytes),'LUA OK: '+unknown(r.lua_ok),'OVERALL OK: '+unknown(r.ok),'CLEANUP OK: '+unknown(r.cleanup_ok),'ERROR TRUNCATED: '+Boolean(r.error_truncated),'OUTPUT TRUNCATED: '+Boolean(r.output_truncated),'INVALID UTF-8 REPLACED: '+Boolean(r.text_sanitized),'','CAPTURED ERROR',r.error||'--','','TRACE',r.trace||'-- (not captured)','','CAPTURED OUTPUT',r.output||'-- (no captured output)','','Temporary local capture. Scrub secrets before sharing.'].join('\\n');}\n"
"async function copy(text){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const area=document.createElement('textarea');area.value=text;area.readOnly=true;area.style.position='fixed';area.style.left='-10000px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error('copy');}$('action-status').textContent='COPIED TO CLIPBOARD';}catch{$('action-status').textContent='COPY UNAVAILABLE \u00b7 use DOWNLOAD .TXT instead.';}}\n"
"document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{if(!report)return;const action=button.dataset.action;if(action==='copy-error')copy(report.error||'--');else if(action==='copy-report')copy(textReport());else{const blob=new Blob([textReport()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ryzobee-report-'+id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('action-status').textContent='REPORT DOWNLOAD REQUESTED';}}));\n"
"$('retry-load').addEventListener('click',load);load();\n"
"</script></body></html>\n";
